3	/**
4	 * Single source of truth for the "normalized telephone" concept shared by the create pipeline:
5	 * {@link ValidateOwner} normalizes the submitted value before storing it, and
6	 * {@link CheckOwnerTelephoneUnique} normalizes stored owner values when comparing for duplicates.
7	 * Keeping the rule here ensures the value that gets stored and the value compared for uniqueness can
8	 * never silently diverge.
9	 */
10	public final class OwnerTelephone {
11	
12	    private OwnerTelephone() {
13	    }
14	
15	    /** Reduce a telephone to its digits; {@code null} becomes the empty string. */
16	    public static String normalize(String value) {
17	        return value == null ? "" : value.replaceAll("\\D", "");
18	    }
19	}
