2	
3	/**
4	 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwner} when the
5	 * owner telephone does not contain exactly ten digits after every non-digit character has been
6	 * stripped. Handled by {@link OwnerTelephoneInvalidExceptionHandler}, which responds 400.
7	 */
8	public class OwnerTelephoneInvalidException extends Exception {
9	
10	    private final String submitted;
11	
12	    public OwnerTelephoneInvalidException(String submitted) {
13	        super("Telephone must contain exactly 10 digits after stripping non-digits: " + submitted);
14	        this.submitted = submitted;
15	    }
16	
17	    public String getSubmitted() {
18	        return this.submitted;
19	    }
20	}
