1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.CheckOwnerTelephoneUnique}
5	 * when the normalized owner telephone being created already belongs to another owner. Handled by
6	 * {@link OwnerTelephoneDuplicateExceptionHandler}, which responds 409.
7	 */
8	public class OwnerTelephoneDuplicateException extends Exception {
9	
10	    private final String telephone;
11	
12	    public OwnerTelephoneDuplicateException(String telephone) {
13	        super("Telephone already in use by another owner: " + telephone);
14	        this.telephone = telephone;
15	    }
16	
17	    public String getTelephone() {
18	        return this.telephone;
19	    }
20	}
